import { Suspense } from 'react'
import { prefetch } from 'next/cache'
import { getRelatedProducts } from '@/lib/data'

export default function ProductPage() {
  return (
    <main>
      <h1>Premium Widget</h1>
      <p>A durable widget for everyday projects.</p>
      <section>
        <h2>Related products</h2>
        <Suspense fallback={<p>Loading related products...</p>}>
          <RelatedProducts />
        </Suspense>
      </section>
    </main>
  )
}

// `await prefetch()` keeps the related products out of the route's App Shell,
// so they are not generated for the default prefetch that every link into the
// route performs. They resolve on a per-link prefetch (`<Link prefetch={true}>`)
// or on the navigation itself. `getRelatedProducts` keeps its `use cache`
// lifetime because the caching directive sits on the function called below it.
async function RelatedProducts() {
  await prefetch()
  const relatedProducts = await getRelatedProducts()
  return (
    <ul>
      {relatedProducts.map((product) => (
        <li key={product}>{product}</li>
      ))}
    </ul>
  )
}

